const canvasPoint = ({ client }, dx = 0, dy = 0) =>
  client.evaluate(`const r = document.querySelector(".tl-canvas").getBoundingClientRect();
    return { x: Math.round(r.left + r.width / 2 + ${dx}), y: Math.round(r.top + r.height / 2 + ${dy}) };`);

const clickAt = async ({ client }, { x, y }, modifiers = 0, button = "left") => {
  for (const type of ["mousePressed", "mouseReleased"]) {
    await client.send("Input.dispatchMouseEvent", {
      type, x, y, button, clickCount: 1, modifiers,
      buttons: type === "mousePressed" ? (button === "right" ? 2 : 1) : 0,
    });
  }
};

// A text shape made the way a user makes one: text tool, click, type, Escape.
const createTextShapeViaToolbar = async (ctx, text) => {
