  await clickAt(ctx, point);
  await client.typeText(text);
  await client.pressEscape();
  await client.waitFor(`return ${TEXT_SHAPES}.length > 0;`, {
    label: "text shape in store",
    timeout: 10000,
  });
  return client.evaluate(`const t = ${TEXT_SHAPES}; const s = t[t.length - 1];
    return { id: s.id, metaKeys: Object.keys(s.meta), propKeys: Object.keys(s.props).sort() };`);
};

