export const VIEW = `app.workspace.getLeavesOfType("tldraw-dg-preview")[0]?.view`;
export const NODE_SEL = '.tl-shape[data-shape-type="discourse-node"]';
export const ADD = 'button[title="Add this relation to canvas"]';
export const REMOVE = 'button[title="Remove this relation from canvas"]';

export const openCanvas = async ({ client, json }, path) => {
  await client.evaluate(`return (async () => {
    app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse();
    const leaf = app.workspace.getLeaf("tab");
    await leaf.setViewState({ type: "tldraw-dg-preview", state: { file: ${json(path)} }, active: true });
    return true;
  })();`);
  await client.waitFor(`return !!document.querySelector(".tl-canvas") && !!document.querySelector(${json(NODE_SEL)});`, {
    label: "canvas with node cards mounted",
    timeout: 15000,
  });
  await new Promise((r) => setTimeout(r, 600));
};

export const clickAt = async ({ client }, { x, y }) => {
  for (const type of ["mousePressed", "mouseReleased"]) {
    await client.send("Input.dispatchMouseEvent", {
      type, x, y, button: "left", clickCount: 1, buttons: type === "mousePressed" ? 1 : 0,
    });
  }
};

export const zoomToFit = async ({ client }) => {
  await clickAt({ client }, await client.evaluate(`const r = document.querySelector(".tl-canvas").getBoundingClientRect();
    return { x: Math.round(r.left + 8), y: Math.round(r.bottom - 8) };`));
  await client.key({ key: "!", code: "Digit1", text: "!", modifiers: 8, windowsVirtualKeyCode: 49, nativeVirtualKeyCode: 49 });
  await new Promise((r) => setTimeout(r, 800));
};

// Click the visible centre of the i-th node card that isn't covered by UI.
export const selectNode = async ({ client, json }, i) => {
  const pt = await client.evaluate(`const els = [...document.querySelectorAll(${json(NODE_SEL)})];
    const el = els[${i}]; if (!el) return null;
    const r = el.getBoundingClientRect();
    return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + Math.min(r.height / 2, 14)) };`);
  if (!pt) return false;
  await clickAt({ client }, pt);
  await new Promise((r) => setTimeout(r, 500));
  return true;
};

export const menuState = ({ client, json }) =>
  client.evaluate(`const tabs = [...document.querySelectorAll(".dg-node-card-menu button[aria-pressed]")]
      .map((b) => b.textContent.trim());
    const legacy = [...document.querySelectorAll(".tl-container button")]
      .filter((b) => b.textContent.trim() === "Relations").length;
    return { tabs, legacy, stylePanel: !!document.querySelector(".tlui-style-panel"),
      add: document.querySelectorAll(${json(ADD)}).length, remove: document.querySelectorAll(${json(REMOVE)}).length,
      text: document.querySelector(".dg-node-card-menu")?.innerText.slice(0, 200) ?? null };`);

export const arrowCount = ({ client }) =>
  client.evaluate(`return ${VIEW}.store.allRecords().filter((r) => r.typeName === "shape" && r.type === "discourse-relation").length;`);

