// ENG-1339: node card context menu is the default; legacy Relations overlay and admin flag are gone.
import { VIEW, NODE_SEL, ADD, REMOVE, clickAt, selectNode, menuState, arrowCount } from "./lib.mjs";

const PLUGIN = `app.plugins.plugins["@discourse-graph/obsidian"]`;
const shared = {}; // canvasPath, pair, relationsBackup — built once, reused by later scenarios

// tldraw's EditorContext value, found by walking the React fiber up from the canvas.
const EDITOR = `(() => {
  const el = document.querySelector(".tl-container");
  const key = Object.keys(el).find((k) => k.startsWith("__reactFiber$"));
  for (let f = el[key]; f; f = f.return) {
    const v = f.memoizedProps?.value;
    if (v && typeof v.putExternalContent === "function") return v;
  }
  return null;
})()`;

// First stored relation whose endpoints are both local discourse-node files.
const findPair = ({ client }) =>
  client.evaluate(`return (async () => {
    const data = JSON.parse(await app.vault.adapter.read("relations.json"));
    const byId = new Map();
    for (const f of app.vault.getMarkdownFiles()) {
      const fm = app.metadataCache.getFileCache(f)?.frontmatter;
      if (fm?.nodeInstanceId && fm?.nodeTypeId && !f.path.startsWith("_verify/")) byId.set(fm.nodeInstanceId, f.path);
    }
    const s = ${PLUGIN}.settings;
    const types = new Set(s.relationTypes.map((t) => t.id));
    for (const r of data.relations) {
      if (r.tentative || !types.has(r.type)) continue;
      const src = byId.get(r.source), dst = byId.get(r.destination);
      if (src && dst && src !== dst) return { id: r.id, src, dst };
    }
    return null;
  })();`);

const buildCanvas = async (ctx) => {
  const { client, json, vault } = ctx;
  shared.relationsBackup = await client.evaluate(`return app.vault.adapter.read("relations.json");`);
  shared.pair = await findPair(ctx);
  if (!shared.pair) throw new Error("no local relation pair in relations.json");
  await client.evaluate(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse();
    return app.commands.executeCommandById(${json(`${vault.pluginId}:create-discourse-graph-canvas`)});`);
  await client.waitFor(`return !!document.querySelector(".tl-canvas") && !!${VIEW}?.file;`, { label: "canvas", timeout: 15000 });
  shared.canvasPath = await client.evaluate(`return ${VIEW}.file.path;`);
  await new Promise((r) => setTimeout(r, 800));
  // Same path a drag from the file explorer takes: the plugin's url external-content handler.
  await client.evaluate(`const ed = ${EDITOR};
    const url = "obsidian://open?vault=" + encodeURIComponent(app.vault.getName()) + "&file=" + encodeURIComponent(${json(shared.pair.src)});
    ed.putExternalContent({ type: "url", url, point: ed.getViewportPageBounds().center });
    return true;`);
  await client.waitFor(`return document.querySelectorAll(${json(NODE_SEL)}).length === 1;`, { label: "source card", timeout: 10000 });
  await new Promise((r) => setTimeout(r, 800));
};

const reopenCanvas = async ({ client, json }) => {
  await client.evaluate(`return (async () => {
    app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse();
    const open = app.workspace.getLeavesOfType("tldraw-dg-preview").find((l) => l.view.file?.path === ${json(shared.canvasPath)});
    const leaf = open ?? app.workspace.getLeaf("tab");
    if (!open) await leaf.setViewState({ type: "tldraw-dg-preview", state: { file: ${json(shared.canvasPath)} }, active: true });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    return true;
  })();`);
  await client.waitFor(`return !!document.querySelector(${json(NODE_SEL)});`, { label: "canvas reopened", timeout: 15000 });
  await new Promise((r) => setTimeout(r, 600));
};

const selectSourceAndWait = async (ctx) => {
  await ctx.client.evaluate(`const ed = ${EDITOR}; ed.setCurrentTool("select"); ed.selectNone(); return true;`);
  await selectNode(ctx, 0);
  await ctx.client.waitFor(
    `return document.querySelectorAll(${ctx.json(`${ADD}, ${REMOVE}`)}).length > 0;`,
    { label: "relation rows loaded", timeout: 10000 },
  );
};

